import { create } from 'zustand';
import type { MediaItem } from '../types';

export const RECENTS_KEY = 'movie-downloader.recents';
export const RECENTS_MAX = 24;

export interface RecentEntry {
  item: MediaItem;
  viewedAt: number;
}

interface RecentsState {
  recents: RecentEntry[];
  record: (item: MediaItem) => void;
  clear: () => void;
}

function loadRecents(): RecentEntry[] {
  try {
    const raw = window.localStorage.getItem(RECENTS_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw) as unknown;
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(isRecentEntry);
  } catch {
    return [];
  }
}

function isRecentEntry(value: unknown): value is RecentEntry {
  if (typeof value !== 'object' || value === null) return false;
  const v = value as { item?: unknown; viewedAt?: unknown };
  if (typeof v.viewedAt !== 'number') return false;
  const item = v.item as Partial<MediaItem> | undefined;
  if (typeof item !== 'object' || item === null) return false;
  return (
    typeof item.tmdbId === 'number' &&
    (item.mediaType === 'movie' || item.mediaType === 'tv') &&
    typeof item.title === 'string'
  );
}

function persist(recents: RecentEntry[]): void {
  try {
    window.localStorage.setItem(RECENTS_KEY, JSON.stringify(recents.slice(0, RECENTS_MAX)));
  } catch {
    // storage may be unavailable (private mode, quota) — degrade to in-memory only
  }
}

export function upsertRecent(recents: RecentEntry[], item: MediaItem): RecentEntry[] {
  const entry: RecentEntry = { item, viewedAt: Date.now() };
  const rest = recents.filter(
    (r) => !(r.item.tmdbId === item.tmdbId && r.item.mediaType === item.mediaType),
  );
  return [entry, ...rest].slice(0, RECENTS_MAX);
}

export const useRecentsStore = create<RecentsState>((set) => ({
  recents: loadRecents(),
  record: (item) =>
    set((s) => {
      const next = upsertRecent(s.recents, item);
      persist(next);
      return { recents: next };
    }),
  clear: () => {
    try {
      window.localStorage.removeItem(RECENTS_KEY);
    } catch {
      // ignore
    }
    set({ recents: [] });
  },
}));

import type { SearchType } from '../types';

const TYPE_FILTERS: Array<{ key: SearchType; label: string }> = [
  { key: 'all', label: 'All' },
  { key: 'movie', label: 'Movies' },
  { key: 'tv', label: 'TV' },
];

interface SearchBarProps {
  query: string;
  type: SearchType;
  onQueryChange: (value: string) => void;
  onTypeChange: (type: SearchType) => void;
  onClear: () => void;
}

export function SearchBar({ query, type, onQueryChange, onTypeChange, onClear }: SearchBarProps) {
  return (
    <div className="search-bar">
      <div className="search-field">
        <svg
          className="search-icon"
          viewBox="0 0 24 24"
          width="20"
          height="20"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          aria-hidden="true"
        >
          <circle cx="11" cy="11" r="7" />
          <path d="m21 21-4.3-4.3" />
        </svg>
        <input
          className="search-input"
          type="search"
          placeholder="Search movies & TV — start typing…"
          value={query}
          onChange={(e) => onQueryChange(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Escape') onClear();
          }}
          aria-label="Search movies and TV"
          autoComplete="off"
          spellCheck={false}
        />
        {query.length > 0 && (
          <button
            type="button"
            className="search-clear"
            onClick={onClear}
            aria-label="Clear search"
            title="Clear search (Esc)"
          >
            ×
          </button>
        )}
      </div>
      <div className="type-filter" role="group" aria-label="Media type">
        {TYPE_FILTERS.map((f) => (
          <button
            key={f.key}
            type="button"
            className={`type-btn ${type === f.key ? 'active' : ''}`}
            onClick={() => onTypeChange(f.key)}
          >
            {f.label}
          </button>
        ))}
      </div>
    </div>
  );
}

import { useRef, type ReactNode } from 'react';

const SCROLL_STEP = 700;

interface SectionRailProps {
  title: string;
  subtitle?: string;
  loading?: boolean;
  emptyHint?: string;
  error?: string | null;
  children: ReactNode;
}

export function SectionRail({ title, subtitle, loading, emptyHint, error, children }: SectionRailProps) {
  const scrollerRef = useRef<HTMLDivElement>(null);

  function scrollBy(direction: -1 | 1): void {
    scrollerRef.current?.scrollBy({ left: direction * SCROLL_STEP, behavior: 'smooth' });
  }

  return (
    <section className="rail">
      <div className="rail-head">
        <div className="rail-title-wrap">
          <h2 className="rail-title">{title}</h2>
          {subtitle && <span className="rail-subtitle">{subtitle}</span>}
        </div>
        <div className="rail-controls">
          <button
            type="button"
            className="rail-arrow"
            onClick={() => scrollBy(-1)}
            aria-label={`Scroll ${title} left`}
          >
            ‹
          </button>
          <button
            type="button"
            className="rail-arrow"
            onClick={() => scrollBy(1)}
            aria-label={`Scroll ${title} right`}
          >
            ›
          </button>
        </div>
      </div>

      {error ? (
        <div className="rail-empty">{error}</div>
      ) : loading ? (
        <div className="poster-row" ref={scrollerRef} aria-hidden="true">
          {Array.from({ length: 10 }).map((_, i) => (
            <div key={i} className="poster-card skeleton" />
          ))}
        </div>
      ) : emptyHint && children == null ? (
        <div className="rail-empty">{emptyHint}</div>
      ) : (
        <div className="poster-row" ref={scrollerRef}>
          {children}
        </div>
      )}
    </section>
  );
}

import { useRef, type ReactNode } from 'react';

