import type { MediaItem } from '../types';
import { backdropUrl } from '../api';

interface HeroSpotlightProps {
  item: MediaItem;
}

export function HeroSpotlight({ item }: HeroSpotlightProps) {
  const backdrop = backdropUrl(item.backdropPath);
