import type { TorrentState } from '../types';
import { STATE_COLORS } from '../types';

export function StateBadge({ state }: { state: TorrentState }) {
  const label = state.replace('-', ' ');
  return (
    <span className={`state-badge state-${STATE_COLORS[state] ?? 'gray'}`} title={state}>
      {label}
    </span>
  );
}
export function Spinner({ label }: { label?: string }) {
  return (
    <div className="spinner-wrap" role="status">
      <span className="spinner" aria-hidden="true" />
      {label ? <span className="spinner-label">{label}</span> : null}
    </div>
  );
}
import { useToastStore } from '../store/toastStore';

export function Toasts() {
  const toasts = useToastStore((s) => s.toasts);
  const dismiss = useToastStore((s) => s.dismiss);
  if (toasts.length === 0) return null;
  return (
    <div className="toasts" aria-live="polite">
      {toasts.map((t) => (
        <button
          key={t.id}
          type="button"
          className={`toast toast-${t.kind}`}
          onClick={() => dismiss(t.id)}
        >
          {t.message}
        </button>
      ))}
    </div>
  );
}
import { useState } from 'react';
import type { Source } from '../types';
import { humanSize } from '../api';

interface SourceRowProps {
  source: Source;
  variants?: Source[];
  onDownload: (source: Source) => void;
  disabled?: boolean;
}

function chipClass(kind: string): string {
  return `chip chip-${kind}`;
}

function QualityChips({ source }: { source: Source }) {
  const chips: Array<{ text: string; cls: string }> = [];
  if (source.resolution) chips.push({ text: source.resolution, cls: 'res' });
