input.content:
:root {
  --bg: #0b0d14;
  --bg-soft: #0f1220;
  --bg-elev: #141827;
  --bg-elev-2: #1b2033;
  --border: rgba(255, 255, 255, 0.08);
  --border-strong: rgba(255, 255, 255, 0.16);
  --text: #f2f4fa;
  --text-dim: #9aa3b8;
  --accent: #7c6cff;
  --accent-2: #4f9cff;
  --green: #2dd57f;
  --red: #ff5d6c;
  --amber: #ffb84d;
  --blue: #4f9cff;
  --orange: #ff8a4d;
  --purple: #b06cff;
  --radius: 12px;
  --radius-lg: 18px;
  --shadow: 0 12px 32px rgba(0, 0, 0, 0.5);
  --glow: 0 0 0 1px rgba(124, 108, 255, 0.4), 0 6px 24px rgba(124, 108, 255, 0.18);
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', sans-serif;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  background:
    radial-gradient(1100px 520px at 85% -10%, rgba(124, 108, 255, 0.14), transparent 60%),
    radial-gradient(900px 480px at -10% 0%, rgba(79, 156, 255, 0.1), transparent 55%),
    var(--bg);
  background-attachment: fixed;
  color: var(--text);
  font-family: var(--font);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font: inherit;
  cursor: pointer;
}

input,
select {
  font: inherit;
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.app {
  min-height: 100%;
  display: flex;
  flex-direction: column;
}

/* Header */
.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 24px;
  position: sticky;
  top: 0;
  z-index: 30;
  background: rgba(11, 13, 20, 0.72);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--border);
}

.brand {
  display: flex;
  align-items: center;
  gap: 9px;
  font-weight: 700;
  font-size: 17px;
  letter-spacing: 0.2px;
}

.brand-mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 8px;
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  color: #fff;
  font-size: 12px;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.conn-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  display: inline-block;
  box-shadow: 0 0 0 3px transparent;
}

.conn-on {
  background: var(--green);
  box-shadow: 0 0 10px rgba(45, 213, 127, 0.6);
}

.conn-off {
  background: var(--red);
}

.app-main {
  flex: 1;
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px 48px;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 9px 16px;
  border-radius: 10px;
  border: 1px solid var(--border-strong);
  background: var(--bg-elev-2);
  color: var(--text);
  font-weight: 600;
  font-size: 14px;
  transition: border-color 0.15s ease, background 0.15s ease, transform 0.15s ease, box-shadow 0.15s ease;
}

.btn:hover:not(:disabled) {
  border-color: var(--accent);
  background: #232946;
  transform: translateY(-1px);
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.btn-primary {
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  border: none;
  color: #fff;
  box-shadow: 0 6px 18px rgba(124, 108, 255, 0.35);
}

.btn-primary:hover:not(:disabled) {
  background: linear-gradient(135deg, #8b7dff, #63a8ff);
  box-shadow: 0 8px 24px rgba(124, 108, 255, 0.45);
}

.btn-danger:hover:not(:disabled) {
  border-color: var(--red);
  color: var(--red);
  background: rgba(255, 93, 108, 0.08);
}

.btn-ghost {
  background: transparent;
}

.btn-sm {
  padding: 5px 10px;
  font-size: 12.5px;
  border-radius: 8px;
}

/* Home hero + search */
.home-hero {
  padding: 42px 0 8px;
  text-align: center;
}

.home-title {
  margin: 0;
  font-size: 40px;
  font-weight: 800;
  letter-spacing: -0.5px;
  background: linear-gradient(120deg, #fff 20%, #c9c3ff 60%, #9ec4ff);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

.home-tagline {
  margin: 8px 0 24px;
  color: var(--text-dim);
  font-size: 15px;
}

.search-bar {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  max-width: 640px;
  margin: 0 auto;
}

.search-field {
  position: relative;
  width: 100%;
  display: flex;
  align-items: center;
}

.search-icon {
  position: absolute;
  left: 18px;
  color: var(--text-dim);
  pointer-events: none;
}

.search-input {
  width: 100%;
  padding: 16px 56px 16px 50px;
  border-radius: 999px;
  border: 1px solid var(--border-strong);
  background: rgba(20, 24, 39, 0.85);
  backdrop-filter: blur(8px);
  color: var(--text);
  font-size: 16px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.search-input::placeholder {
  color: #6b7488;
}

.search-input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 4px rgba(124, 108, 255, 0.18), 0 10px 30px rgba(0, 0, 0, 0.35);
}

.search-input::-webkit-search-cancel-button {
  display: none;
}

.search-clear {
  position: absolute;
  right: 10px;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: none;
  background: var(--bg-elev-2);
  color: var(--text-dim);
  font-size: 20px;
  line-height: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.search-clear:hover {
  color: var(--text);
  background: var(--border-strong);
}

.type-filter {
  display: flex;
  gap: 8px;
}

.type-btn {
  padding: 6px 16px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: transparent;
  color: var(--text-dim);
  font-weight: 500;
  font-size: 13px;
  transition: all 0.15s ease;
}

.type-btn:hover {
  color: var(--text);
  border-color: var(--border-strong);
}

.type-btn.active {
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  border-color: transparent;
  color: #fff;
}

/* Browse + rails */
.browse {
  margin-top: 28px;
  display: flex;
  flex-direction: column;
  gap: 34px;
}

.rail {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.rail-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
}

.rail-title-wrap {
  display: flex;
  align-items: baseline;
  gap: 12px;
  min-width: 0;
}

.rail-title {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
  letter-spacing: -0.2px;
}

.rail-subtitle {
  color: var(--text-dim);
  font-size: 13px;
  white-space: nowrap;
}

.rail-controls {
  display: flex;
  gap: 8px;
}

.rail-arrow {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 1px solid var(--border);
  background: var(--bg-elev-2);
  color: var(--text-dim);
  font-size: 20px;
  line-height: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: all 0.15s ease;
}

.rail-arrow:hover {
  color: #fff;
  border-color: var(--accent);
  box-shadow: var(--glow);
}

.rail-empty {
  color: var(--text-dim);
  font-size: 14px;
  padding: 26px 20px;
  border: 1px dashed var(--border-strong);
  border-radius: var(--radius-lg);
  background: rgba(20, 24, 39, 0.4);
}

/* Poster rows */
.poster-row {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: 158px;
  gap: 16px;
  overflow-x: auto;
  padding: 4px 2px 12px;
  scroll-snap-type: x proximity;
  scrollbar-width: none;
}

.poster-row::-webkit-scrollbar {
  display: none;
}

/* Poster cards */
.poster-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 20px;
}

.poster-link {
  border: none;
  background: none;
  padding: 0;
  margin: 0;
  text-align: left;
  color: inherit;
  scroll-snap-align: start;
}

.poster-card {
  position: relative;
  aspect-ratio: 2 / 3;
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--bg-elev-2);
  border: 1px solid var(--border);
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.3);
  transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
}

.poster-link:hover .poster-card {
  transform: translateY(-6px) scale(1.02);
  border-color: rgba(124, 108, 255, 0.65);
  box-shadow: var(--glow);
}

.poster-card-image {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.35s ease;
}

.poster-link:hover .poster-card-image {
  transform: scale(1.08);
}

.poster-card-placeholder {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 44px;
  font-weight: 700;
  color: var(--text-dim);
  background: linear-gradient(135deg, var(--bg-elev), var(--bg-elev-2));
}

.poster-card-shade {
  position: absolute;
  inset: auto 0 0 0;
  height: 62%;
  background: linear-gradient(to top, rgba(0, 0, 0, 0.92) 8%, rgba(0, 0, 0, 0.55) 45%, transparent 100%);
  pointer-events: none;
}

.poster-card-rating {
  position: absolute;
  top: 8px;
  right: 8px;
  padding: 3px 8px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 700;
  color: var(--amber);
  background: rgba(10, 12, 18, 0.72);
  backdrop-filter: blur(4px);
  border: 1px solid rgba(255, 184, 77, 0.25);
}

.poster-card-info {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 28px 12px 12px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.poster-card-title {
  margin: 0;
  font-size: 13.5px;
  font-weight: 600;
  line-height: 1.25;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.poster-card-year {
  color: var(--text-dim);
  font-size: 12px;
}

.poster-card-progress {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 5px;
  background: rgba(255, 255, 255, 0.14);
}

.poster-card-progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--accent), var(--accent-2));
  transition: width 0.4s ease;
}

.poster-card.skeleton {
  border: 1px solid var(--border);
  background: linear-gradient(100deg, var(--bg-elev-2) 30%, #252b44 50%, var(--bg-elev-2) 70%);
  background-size: 200% 100%;
  animation: shimmer 1.4s infinite linear;
}

.poster-grid > .poster-card.skeleton {
  width: 100%;
}

@keyframes shimmer {
  to {
    background-position: -200% 0;
  }
}

/* Search results */
.search-results {
  margin-top: 30px;
}

.search-results-head {
  display: flex;
  align-items: baseline;
  gap: 14px;
  margin-bottom: 18px;
}

/* Hero spotlight */
.hero-spotlight {
  position: relative;
  display: block;
  border-radius: var(--radius-lg);
  overflow: hidden;
  min-height: 440px;
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
}

.hero-spotlight-backdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero-spotlight-shade {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(to top, rgba(11, 13, 20, 0.97) 0%, rgba(11, 13, 20, 0.6) 34%, rgba(11, 13, 20, 0.12) 70%),
    linear-gradient(to right, rgba(11, 13, 20, 0.65) 0%, transparent 55%);
}

.hero-spotlight-content {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-end;
  gap: 10px;
  min-height: 440px;
  padding: 40px;
  max-width: 620px;
}

.hero-spotlight-kicker {
  text-transform: uppercase;
  letter-spacing: 2.5px;
  font-size: 12px;
  font-weight: 700;
  color: var(--accent-2);
}

.hero-spotlight-title {
  margin: 0;
  font-size: 40px;
  line-height: 1.08;
  letter-spacing: -0.6px;
  text-shadow: 0 2px 20px rgba(0, 0, 0, 0.5);
}

.hero-spotlight-meta {
  display: flex;
  gap: 14px;
  color: var(--text-dim);
  font-size: 14px;
}

.hero-spotlight-rating {
  color: var(--amber);
  font-weight: 700;
}

.hero-spotlight-overview {
  margin: 0;
  color: rgba(242, 244, 250, 0.82);
  font-size: 14.5px;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.hero-spotlight-cta {
  margin-top: 8px;
}

.hero-spotlight--skeleton {
  min-height: 440px;
  background: linear-gradient(100deg, var(--bg-elev) 30%, var(--bg-elev-2) 50%, var(--bg-elev) 70%);
  background-size: 200% 100%;
  animation: shimmer 1.4s infinite linear;
}

/* Detail */
.detail-page {
  padding-top: 24px;
}

.hero {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  min-height: 380px;
  display: flex;
  align-items: flex-end;
  margin-bottom: 30px;
  background: var(--bg-elev);
  box-shadow: var(--shadow);
}

.hero-backdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero-shade {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(to top, var(--bg) 0%, rgba(11, 13, 20, 0.55) 45%, rgba(11, 13, 20, 0.15) 100%);
}

.hero-content {
  position: relative;
  padding: 30px;
  max-width: 780px;
}

.hero-title {
  margin: 0 0 8px;
  font-size: 38px;
  line-height: 1.1;
  letter-spacing: -0.4px;
}

.hero-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  color: var(--text-dim);
  margin-bottom: 12px;
}

.hero-rating {
  color: var(--amber);
  font-weight: 700;
}

.hero-overview {
  margin: 0 0 18px;
  opacity: 0.9;
  max-width: 660px;
}

.sources-section h2 {
  margin: 0 0 12px;
}

/* Detail: filters + sources */
.sources-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.sources-head h2 {
