/** @type {import('tailwindcss').Config} */
export default {
  darkMode: 'class',
  content: ['./index.html', './src/**/*.{ts,tsx}'],
  corePlugins: { preflight: false },
  theme: {
    extend: {
      colors: {
        border: 'hsl(var(--border))',
        input: 'hsl(var(--input))',
        ring: 'hsl(var(--ring))',
        background: 'hsl(var(--background))',
        foreground: 'hsl(var(--foreground))',
        primary: {
          DEFAULT: 'hsl(var(--primary))',
          foreground: 'hsl(var(--primary-foreground))',
        },
        secondary: {
          DEFAULT: 'hsl(var(--secondary))',
          foreground: 'hsl(var(--secondary-foreground))',
        },
        destructive: {
          DEFAULT: 'hsl(var(--destructive))',
          foreground: 'hsl(var(--destructive-foreground))',
        },
        muted: {
          DEFAULT: 'hsl(var(--muted))',
          foreground: 'hsl(var(--muted-foreground))',
        },
        accent: {
          DEFAULT: 'hsl(var(--accent))',
          foreground: 'hsl(var(--accent-foreground))',
        },
        popover: {
          DEFAULT: 'hsl(var(--popover))',
          foreground: 'hsl(var(--popover-foreground))',
        },
        card: {
          DEFAULT: 'hsl(var(--card))',
          foreground: 'hsl(var(--card-foreground))',
        },
        sidebar: {
          DEFAULT: 'hsl(var(--sidebar-background))',
          foreground: 'hsl(var(--sidebar-foreground))',
          primary: 'hsl(var(--sidebar-primary))',
          'primary-foreground': 'hsl(var(--sidebar-primary-foreground))',
          accent: 'hsl(var(--sidebar-accent))',
          'accent-foreground': 'hsl(var(--sidebar-accent-foreground))',
          border: 'hsl(var(--sidebar-border))',
          ring: 'hsl(var(--sidebar-ring))',
        },
      },
      borderRadius: {
        lg: 'var(--radius)',
        md: 'calc(var(--radius) - 2px)',
        sm: 'calc(var(--radius) - 4px)',
      },
      keyframes: {
        'accordion-down': {
          from: { height: '0' },
          to: { height: 'var(--radix-accordion-content-height)' },
        },
        'accordion-up': {
          from: { height: 'var(--radix-accordion-content-height)' },
          to: { height: '0' },
        },
      },
      animation: {
        'accordion-down': 'accordion-down 0.2s ease-out',
        'accordion-up': 'accordion-up 0.2s ease-out',
      },
    },
  },
  plugins: [],
};

export default {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
};

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    /* shadcn semantic tokens — mapped to the app's dark palette */
    --background: 229 30% 6%;
    --foreground: 229 60% 96%;
    --card: 228 30% 12%;
    --card-foreground: 229 60% 96%;
    --popover: 228 30% 12%;
    --popover-foreground: 229 60% 96%;
    --primary: 247 100% 71%;
    --primary-foreground: 0 0% 100%;
    --secondary: 224 31% 16%;
    --secondary-foreground: 229 60% 96%;
    --muted: 224 26% 14%;
    --muted-foreground: 224 17% 66%;
    --accent: 230 34% 17%;
    --accent-foreground: 229 60% 96%;
    --destructive: 355 100% 68%;
    --destructive-foreground: 0 0% 100%;
    --border: 226 20% 18%;
    --input: 226 20% 18%;
    --ring: 247 100% 71%;
    --radius: 0.75rem;

    /* sidebar tokens */
    --sidebar-background: 228 28% 8%;
    --sidebar-foreground: 229 45% 88%;
    --sidebar-primary: 247 100% 71%;
    --sidebar-primary-foreground: 0 0% 100%;
    --sidebar-accent: 228 30% 14%;
    --sidebar-accent-foreground: 229 60% 96%;
    --sidebar-border: 226 20% 14%;
    --sidebar-ring: 247 100% 71%;
  }
}

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

