.settings-card .rail-title {
  margin-bottom: 10px;
}

.settings-note {
  color: var(--text-dim);
  font-size: 13.5px;
  margin: 0 0 14px;
}

.settings-note code,
.settings-list code {
  background: var(--bg-elev-2);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 1px 6px;
  font-size: 12.5px;
  color: #b3aaff;
}

.settings-list {
  margin: 0;
  display: flex;
  flex-direction: column;
}

.settings-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  padding: 10px 0;
  border-bottom: 1px solid var(--border);
}

.settings-row:last-child {
  border-bottom: none;
}

.settings-row dt {
  font-weight: 600;
  color: var(--text);
  font-size: 14px;
}

.settings-row dd {
  margin: 0;
  color: var(--text-dim);
  font-size: 13.5px;
  text-align: right;
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

@media (max-width: 560px) {
  .settings-row {
    flex-direction: column;
    gap: 2px;
  }

  .settings-row dd {
    text-align: left;
  }
}

/* Responsive */

